const raw = $input.first()?.json || {};
let bundle = raw;
if (raw && raw.data) {
  try {
    bundle = typeof raw.data === 'string' ? JSON.parse(raw.data) : raw.data;
  } catch (e) {
    bundle = raw;
  }
} else if (typeof raw === 'string') {
  try { bundle = JSON.parse(raw); } catch (e) {}
}

const patients = [];
if (bundle.entry && Array.isArray(bundle.entry)) {
  for (const entry of bundle.entry) {
    const p = entry.resource;
    if (!p || p.resourceType !== 'Patient') continue;

    const patientUuid = p.id;

    let openmrsId = '';
    if (p.identifier && Array.isArray(p.identifier)) {
      const idObj = p.identifier.find(i => 
        (i.type && i.type.text === 'OpenMRS ID') ||
        (i.type && i.type.coding && i.type.coding.some(c => c.code === '05a29f94-c0ed-11e2-94be-8c13b969e334'))
      ) || p.identifier[0];
      if (idObj) openmrsId = idObj.value || '';
    }

    let given = '';
    let family = '';
    if (p.name && p.name.length > 0) {
      const nameObj = p.name[0];
      given = (nameObj.given || []).join(' ');
      family = nameObj.family || '';
    }
    const fullName = `${given} ${family}`.trim() || `Patient ${openmrsId || patientUuid}`;

    let phone = '';
    if (p.telecom && Array.isArray(p.telecom)) {
      const tel = p.telecom.find(t => t.system === 'phone') || p.telecom[0];
      if (tel) phone = tel.value || '';
    }

    let street = '';
    let city = '';
    let state = '';
    let postalCode = '';
    let country = '';
    if (p.address && p.address.length > 0) {
      const addr = p.address[0];
      if (addr.line && Array.isArray(addr.line)) {
        street = addr.line.join(', ');
      } else if (addr.extension) {
        const lineExt = addr.extension.find(e => e.url && e.url.includes('address1'));
        if (lineExt) street = lineExt.valueString || '';
      }
      city = addr.city || '';
      state = addr.state || '';
      postalCode = addr.postalCode || '';
      country = addr.country || '';
    }

    patients.push({
      patient_uuid: patientUuid,
      openmrs_id: openmrsId,
      full_name: fullName,
      birth_date: p.birthDate || '',
      gender: p.gender || '',
      phone: phone,
      street: street,
      city: city,
      state: state,
      postal_code: postalCode,
      country: country,
      comment: `OpenMRS Master Patient Index | ID: ${openmrsId} | UUID: ${patientUuid} | DOB: ${p.birthDate || 'N/A'}`
    });
  }
}

return [{
  json: {
    patients: patients,
    patient_uuids: patients.map(p => p.patient_uuid)
  }
}];

const items = $input.all();
const partners = [];
for (const item of items) {
  const j = item.json;
  if (Array.isArray(j)) {
    partners.push(...j);
  } else if (j && Array.isArray(j.body)) {
    partners.push(...j.body);
  } else if (j && j.id) {
    partners.push(j);
  }
}
const existingRefs = new Set(partners.map(p => p.ref).filter(Boolean));

const prevData = $('Parse Demographics & Prepare Lookup').first()?.json || {};
const allPatients = prevData.patients || [];

const missing = allPatients.filter(p => !existingRefs.has(p.patient_uuid));

if (missing.length === 0) {
  return [{
    json: {
      has_missing: false,
      missing_count: 0,
      vals_list: []
    }
  }];
}

const valsList = missing.map(p => ({
  name: p.full_name,
  ref: p.patient_uuid,
  customer_rank: 1,
  phone: p.phone,
  street: p.street,
  city: p.city,
  zip: p.postal_code,
  comment: p.comment
}));

return [{
  json: {
    has_missing: true,
    missing_count: valsList.length,
    vals_list: valsList
  }
}];

const result = $input.first()?.json;
const count = $('Partition Missing Partners').first()?.json?.missing_count || 0;
return [{
  json: {
    status: 'SUCCESS',
    operation: 'BATCH_CREATE',
    created_count: count,
    odoo_ids: result,
    timestamp: new Date().toISOString()
  }
}];

return [{
  json: {
    status: 'SUCCESS',
    operation: 'NONE',
    message: 'All OpenMRS patients already exist in Odoo',
    timestamp: new Date().toISOString()
  }
}];
